CacheEncryptionProviderAsyncWaiter::~CacheEncryptionProviderAsyncWaiter() = default;


void CacheEncryptionProviderAsyncWaiter::GetEncryptor(
    ::os_crypt_async::mojom::EncryptorPtr* out_encryptor) {
  base::RunLoop loop;
  proxy_->GetEncryptor(
      base::BindOnce(
          [](base::RunLoop* loop,
             ::os_crypt_async::mojom::EncryptorPtr* out_encryptor
,
             ::os_crypt_async::mojom::EncryptorPtr encryptor) {*out_encryptor = std::move(encryptor);
            loop->Quit();
          },
          &loop,
          out_encryptor));
  loop.Run();
}

::os_crypt_async::mojom::EncryptorPtr CacheEncryptionProviderAsyncWaiter::GetEncryptor(
    ) {
  ::os_crypt_async::mojom::EncryptorPtr async_wait_result;
  GetEncryptor(&async_wait_result);
  return async_wait_result;
}

void CacheEncryptionProviderAsyncWaiter::GetEncryptedCacheEncryptionKey(
    std::vector<uint8_t>* out_encrypted_key) {
  base::RunLoop loop;
  proxy_->GetEncryptedCacheEncryptionKey(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<uint8_t>* out_encrypted_key
,
             const std::vector<uint8_t>& encrypted_key) {*out_encrypted_key = std::move(encrypted_key);
            loop->Quit();
          },
          &loop,
          out_encrypted_key));
  loop.Run();
}

std::vector<uint8_t> CacheEncryptionProviderAsyncWaiter::GetEncryptedCacheEncryptionKey(
    ) {
  std::vector<uint8_t> async_wait_result;
  GetEncryptedCacheEncryptionKey(&async_wait_result);
  return async_wait_result;
}






